{"files": 
[{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林晚",
      "role": "protagonist",
      "identity": "烈士遗孤，政治联姻的新娘",
      "traits": ["坚韧", "隐忍", "聪慧", "忠诚", "深情"],
      "overt_motivation": "完成组织安排的政治联姻任务",
      "covert_motivation": "保护十年前战场上的青梅竹马，不让他因自己的存在而陷入危险",
      "secret_fear": "害怕承认旧情会毁掉他现在的政治前途和生命安全",
      "misperception_of_other": "以为他当年在战场上已经牺牲，现在只是长得相似的陌生人",
      "hidden_connection": "十年前在边境战场，他曾为她挡下致命子弹，她以为他死了"
    },
    {
      "name": "陆铮",
      "role": "deuteragonist",
      "identity": "红三代少将，政治联姻的新郎",
      "traits": ["克制", "忠诚", "勇敢", "深情", "责任感强"],
      "overt_motivation": "服从组织安排，完成政治联姻任务",
      "covert_motivation": "保护她不被卷入政治漩涡，用冷漠伪装来确保她的安全",
      "secret_fear": "害怕她发现他还活着会重新燃起希望，最终导致更大的伤害",
      "misperception_of_other": "以为她在战场上失明后被送走，现在只是巧合的相似",
      "hidden_connection": "背上的枪伤是当年为她挡的，但他谎称是训练中受伤"
    }
  ],
  "supporting_characters": [
    {
      "name": "岗哨小李",
      "function": "阻碍",
      "identity": "军区大院巡逻岗哨",
      "description": "定时巡逻的年轻士兵，代表无处不在的监视和规则约束"
    },
    {
      "name": "政委王主任",
      "function": "阻碍",
      "identity": "政治部主任",
      "description": "负责监督政治联姻的执行情况，代表组织权威"
    },
    {
      "name": "老班长",
      "function": "反转点",
      "identity": "陆铮的前班长",
      "description": "知道当年战场真相的老兵，可能成为揭露秘密的关键人物"
    }
  ],
  "relationship_dynamics": "两人在密闭的军区大院新房中，必须装作完全陌生的政治联姻夫妻，但旧情在压抑的环境中不断复燃。每一次亲密接触都是对组织的背叛，每一次克制都是对彼此的保护。他们的爱情本身就是最大的敌人，因为承认它就意味着毁灭。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立军区大院的政治联姻背景，引入主角身份和核心冲突。新婚夜发现彼此是失散十年的青梅竹马，但必须装作完全陌生。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "红色喜庆下的陌生人",
        "core_event": "林晚和陆铮在军区大院举行政治联姻婚礼，新婚夜在压抑的红色新房中发现彼此就是十年前战场上的青梅竹马。",
        "emotional_tone": "压抑、震惊、克制",
        "key_scenes": [
          "婚礼仪式的官方庄重与个人情感的撕裂",
          "新房内红色喜庆装饰与窗外岗哨的对比",
          "新婚夜相认时的眼神交流和无声确认",
          "第一次用手势暗语对话的紧张时刻"
        ]
      }
    ],
    "turning_point": "两人决定继续伪装成完全陌生的政治联姻夫妻，但内心已无法回到从前。"
  },
  "act_two": {
    "description": "在密闭空间中，旧情不断复燃但又被政治任务压制。通过战场暗语、深夜亲密等方式建立秘密连接，同时外部压力不断增加。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "暗语与伤疤",
        "core_event": "林晚发现陆铮背上的枪伤就是当年为她挡的那颗子弹留下的，但他坚称是训练中受伤。两人开始用手势暗语在岗哨巡逻时秘密交流。",
        "emotional_tone": "痛苦、渴望、隐秘的甜蜜",
        "key_scenes": [
          "深夜岗哨巡逻时的安静亲密",
          "发现伤疤真相的震撼时刻",
          "用手势暗语调情的危险游戏",
          "结婚证从政治文件变成承载旧物记忆的载体"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "监听电话里的沉默",
        "core_event": "政委要求他们定期汇报婚姻状况，两人在被监听的电话中只能用官方语言交流，但通过微小细节传递真实情感。",
        "emotional_tone": "焦虑、压抑、绝望中的希望",
        "key_scenes": [
          "被监听电话中的官方对话",
          "通过军装纽扣位置传递信息",
          "老班长意外来访带来的危机",
          "两人在公共场合的完美伪装"
        ]
      }
    ],
    "turning_point": "老班长透露当年战场的更多真相，让两人意识到他们的重逢可能不是偶然，而是有人故意安排的政治陷阱。"
  },
  "act_three": {
    "description": "政治压力达到顶点，两人必须在爱情和政治忠诚间做出最终选择。牺牲成为唯一的出路，但牺牲的方式决定了故事的结局。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "必须牺牲所爱",
        "core_event": "政委给出最后通牒：要么彻底断绝私人情感专心政治任务，要么其中一人主动申请调离。两人意识到必须有人做出牺牲。",
        "emotional_tone": "绝望、决绝、深沉的爱",
        "key_scenes": [
          "最后通牒的残酷现实",
          "两人在岗哨间隙的最后一次亲密",
          "林晚决定主动申请调离以保护陆铮",
          "陆铮发现她的计划并抢先一步行动"
        ]
      },
      {
        "chapter_number": 5,
        "chapter_title": "毁灭或重生",
        "core_event": "陆铮选择牺牲自己，主动承认违反政治纪律，承担所有责任。林晚在离开前收到他留下的最后一份'结婚证'，里面夹着当年的战场照片。",
        "emotional_tone": "悲壮、释然、永恒的爱",
        "key_scenes": [
          "陆铮向组织坦白一切",
          "林晚在岗哨外远远看着他的背影",
          "最后一份结婚证作为情书的传递",
          "开放式结局：她带着真相离开，他承担后果留下"
        ]
      }
    ]
  }
}"}]

}

